INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24301, 'Luke 11:23', 'Luke', 11, 23, '&nbsp;څوک چې ما سره نۀ دے، هغه زما خلاف دے. څوک يې چې ما سره يو ځائ نه راټولوى نو هغه يې نولى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24302, 'Luke 11:24', 'Luke', 11, 24, '&nbsp;کله چې د يو کس نه پيرے بهر شى نو هغه په صحراګانو سر شى چې آرام ومومى، خو چې وې نۀ مومى نو هغه بيا د خپل ځان سره داسې ووائى چې زۀ به واپس هغه ځائ ته لاړ شم د کوم نه چې راوتلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24303, 'Luke 11:25', 'Luke', 11, 25, '&nbsp;نو هغه چې واپس راشى نو هغه ځائ صفا او جارُو کړے او د اوسېدو جوګه بيامومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24304, 'Luke 11:26', 'Luke', 11, 26, '&nbsp;بيا هغه لاړ شى او نور اووۀ پيريان د ځان سره راولى چې د دۀ نه هم زيات خراب وى او هغوئ ټول راشى او په پيرى نيولى کس دېره شى او د هغۀ اَنجام د پخوا نه هم لا خراب شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24305, 'Luke 11:27', 'Luke', 11, 27, '&nbsp;کله چې عيسىٰ دا خبره کوله په ګڼه کښې يوې ښځې چغې کړې، ”بختوره ده هغه مور چې تۀ يې زيږولے يې او تا له يې پئ درکړى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24306, 'Luke 11:28', 'Luke', 11, 28, '&nbsp;نو هغۀ جواب ورکړو، ”نه، بختور هغه دى څوک چې د خُدائ پاک کلام اورى او عمل پرې کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24307, 'Luke 11:29', 'Luke', 11, 29, '&nbsp;کله چې عيسىٰ ته د خلقو ګڼه زياتېدله نو هغۀ داسې وفرمائيل، ”دا يوه ګناهګاره پيړۍ ده. دوئ نښې غواړى خو د يُونس نبى د نښې نه سېوا يوه نښه به هم دوئ له ورنۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24308, 'Luke 11:30', 'Luke', 11, 30, '&nbsp;لکه څنګه چې يُونس د نينوه د خلقو دپاره نښه وګرځېدو، دغه شان به اِبن آدم هم د دې پيړۍ دپاره نښه وګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24309, 'Luke 11:31', 'Luke', 11, 31, '&nbsp;د شيبا مَلِکه به د قيامت په ورځ د دې پيړۍ د خلقو خلاف په عدالت کښې ودريږى او دوئ به مجرمان ثابت کړى، ځکه چې هغه د دُنيا د بل سر نه د سليمان د حِکمت خبرو اورېدو له راغلې وه، او څوک چې دلته دے هغه د سليمان نه هم لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24310, 'Luke 11:32', 'Luke', 11, 32, '&nbsp;د نينوه خلق به هم د دې زمانې د خلقو په خلاف د قيامت په ورځ ودريږى او دا پيړۍ به مجرمه ثابته کړى ځکه چې هغوئ د يُونس په بيان توبه ګار شوى وُو، او اوس څوک چې دلته دے، هغه د يُونس نه لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24311, 'Luke 11:33', 'Luke', 11, 33, '&nbsp;هيڅوک بله شوې ډيوه په پټ ځائ کښې او يا د لوښى لاندې نۀ ږدى بلکې د ډيوټ دپاسه يې ږدى چې کور ته راتلونکى خلق يې رڼا ووينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24312, 'Luke 11:34', 'Luke', 11, 34, '&nbsp;ستا سترګې ستا د بدن دپاره ډيوې دى. کۀ ستا سترګې روغې وى، نو ستا ټول بدن به د رڼا نه ډک وى. خو کۀ ستا سترګې خرابې وى، نو ستا په ټول بدن کښې به تورتم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24313, 'Luke 11:35', 'Luke', 11, 35, '&nbsp;نو بيا پام کوه چې کومه رڼا په تا کښې ده چې هغه تورتم نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24314, 'Luke 11:36', 'Luke', 11, 36, '&nbsp;کۀ چرې ستا ټول بدن د رڼا نه ډک وى، او يو اندام دې هم په تورتم کښې نۀ وى، نو ستا ټول ژوندون به روښانه وى، داسې لکه چې يوه ډيوه په تا ځليږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24315, 'Luke 11:37', 'Luke', 11, 37, '&nbsp;کله چې عيسىٰ خبرې ختمې کړې نو يو فريسى هغۀ ته د روټۍ دعوت ورکړو. هغه دننه ورغلو او ورسره کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24316, 'Luke 11:38', 'Luke', 11, 38, '&nbsp;فريسى په دې ليدو حېران شو چې هغۀ د روټۍ خوړلو نه مخکښې لاسونه ونۀ وينځل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24317, 'Luke 11:39', 'Luke', 11, 39, '&nbsp;خو مالِک هغۀ ته وفرمائيل، ”تاسو فريسيان خو د کنډول او رکېبۍ بهر مخ وينځئ خو دننه تاسو د حرص او بدکارۍ نه ډک کړى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24318, 'Luke 11:40', 'Luke', 11, 40, '&nbsp;اے کم عقلو، چا چې بهرنۍ حِصه جوړه کړې ده، ولې هغۀ دننه حِصه نۀ ده جوړه کړې څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24319, 'Luke 11:41', 'Luke', 11, 41, '&nbsp;خو څۀ چې ستاسو په لوښو کښې دى هغه خېراتى ورکړئ. نو بيا به تاسو دننه او بهر مکمل پاک شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24320, 'Luke 11:42', 'Luke', 11, 42, '&nbsp;اے فريسيانو، په تاسو دې افسوس وى. تاسو د باغ د پودينې او سپېلنو او د هر قِسم سبزۍ لسمه حِصه خو ورکوئ خو د اِنصاف او د خُدائ پاک سره د مينې نه اِنکار کوئ. په کار خو دا وو چې تاسو په دې هم عمل کولے او هغه مو هم نۀ پرېښودلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24321, 'Luke 11:43', 'Luke', 11, 43, '&nbsp;اے فريسيانو، په تاسو دې افسوس وى. تاسو په عبادتخانو کښې د مشرۍ کُرسۍ خوښوئ او په بازارونو کښې په سلامونو ډېر خوشحالېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24322, 'Luke 11:44', 'Luke', 11, 44, '&nbsp;افسوس چې تاسو د هغه قبرونو په شان يئ چې نښه يې نۀ معلوميږى او خلق پرې په بې‌خيالۍ سره دپاسه ګرځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24323, 'Luke 11:45', 'Luke', 11, 45, '&nbsp;د دې په جواب کښې يو د شرعې عالم ووئيل، ”اُستاذه، کله چې تاسو داسې خبرې کوئ نو دا زمونږه سپکاوے کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24324, 'Luke 11:46', 'Luke', 11, 46, '&nbsp;عيسىٰ ورته وفرمائيل، ”اے د شرعې عالمانو په تاسو دې هم افسوس وى. ځکه چې تاسو په خلقو بې‌اندازې بوج وراچوئ ولې په خپله د دې د اوچتولو دپاره يوه ګوته قدرې هم نۀ وروړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24325, 'Luke 11:47', 'Luke', 11, 47, '&nbsp;په تاسو دې افسوس وى چې تاسو د هغه نبيانو زيارتونه جوړَوئ کوم نبيان چې ستاسو پلار نيکونو وژلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24326, 'Luke 11:48', 'Luke', 11, 48, '&nbsp;او تاسو په خپله په دې کار د خپل پلار نيکۀ په جرمونو کښې شريک شوئ، هغوئ پېغمبران ووژل او تاسو پرې زيارتونه جوړ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24327, 'Luke 11:49', 'Luke', 11, 49, '&nbsp;ځکه خو خُدائ پاک په خپل حِکمت کښې وئيلى دى چې زۀ به تاسو ته نبيان او رسولان درولېږم او په دوئ کښې به ځينې ووژلے شى او ځينې به وزورولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24328, 'Luke 11:50', 'Luke', 11, 50, '&nbsp;نو دغه شان به د دُنيا د شروع نه تر اوسه پورې د دې موجوده پيړۍ نه د ټولو نبيانو د تويو شوو وينو تپوس وکړے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24329, 'Luke 11:51', 'Luke', 11, 51, '&nbsp;د هابيل د وينې نه د زکرياه تر وينې پورې، څوک چې د خُدائ د کور او قربان‌ګاه په مينځ کښې وژلے شوے وو. زۀ تاسو ته دا وايم، چې دې پيړۍ ته به د دې ټولو د وينو تويولو سزا ملاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24330, 'Luke 11:52', 'Luke', 11, 52, '&nbsp;اے د شرعې عالمانو، په تاسو دې افسوس وى. ځکه چې تاسو د عِلم کُنجيانې قبضه کړې دى، تاسو په خپله هم په کښې داخل نۀ شوئ او څوک چې داخلېدل هغوئ مو هم پرې نۀ ښودل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24331, 'Luke 11:53', 'Luke', 11, 53, '&nbsp;کله چې عيسىٰ د کوره بهر شو نو فريسيانو او د شرعې عالمانو دا کوشش وکړو چې د هغۀ سخت مخالفت شروع کړى او د دۀ نه بې‌واره بې‌واره تپوسونه وکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24332, 'Luke 11:54', 'Luke', 11, 54, '&nbsp;او په دې اِنتظار وُو چې هغه په خپلو خبرو کښې راګېر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24333, 'Luke 12:1', 'Luke', 12, 1, '&nbsp;په دې دوران کښې د زرګونو خلقو ګڼه جوړه شوې وه او داسې ټيل جوړ شوے وو چې خلقو يو بل د پښو لاندې کول. نو عيسىٰ اول خپلو مريدانو ته خبرې شروع کړې چې، ”د فريسيانو د خمبيرې نه ځان ساتئ. زما مطلب د هغوئ د منافقت نه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24334, 'Luke 12:2', 'Luke', 12, 2, '&nbsp;داسې يو پټ څيز نشته چې هغه به ښکاره نۀ شى او نۀ داسې پټ راز شته چې هغه به ښکاره نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24335, 'Luke 12:3', 'Luke', 12, 3, '&nbsp;نو هر هغه څۀ چې تاسو په تيارۀ کښې وايئ، هغه به په رڼا ورځ واورېدلے شى او هغه څۀ چې تاسو په بندو کمرو کښې يو بل ته په غوږ کښې وئيلى دى، هغه به د چت نه په چغه واورولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24336, 'Luke 12:4', 'Luke', 12, 4, '&nbsp;اے دوستانو، زۀ تاسو ته دا وايم، د هغه چا نه مۀ يرېږئ څوک چې ستاسو بدن وژنى خو د مرګ نه پس نور تاسو سره هيڅ نۀ شى کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24337, 'Luke 12:5', 'Luke', 12, 5, '&nbsp;خو زۀ به تاسو خبردار کړم چې د چا نه يره په کار ده. د هغه چا نه يرېږئ څوک چې د وژلو نه پس دوزخ ته د اچولو طاقت هم لرى. آو، زۀ تاسو ته وايم چې د هم هغۀ نه يره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24338, 'Luke 12:6', 'Luke', 12, 6, '&nbsp;ولې پينځۀ چڼچڼې په دوو پېسو نۀ خرڅيږى څۀ؟ او خُدائ پاک بيا هم په دوئ کښې يوه هم نۀ هېروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24339, 'Luke 12:7', 'Luke', 12, 7, '&nbsp;خو ستاسو د سر ټول وېښتۀ هم شمېرلے شوى دى. نو بيا مۀ يرېږئ، تاسو د بې‌شمېره چڼچڼو نه زيات قيمتى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24340, 'Luke 12:8', 'Luke', 12, 8, '&nbsp;زۀ تاسو ته رښتيا وايم چې هر هغه څوک چې د خلقو په وړاندې زما اِقرار وکړى نو اِبن آدم به هم د خُدائ پاک د فرښتو په وړاندې د هغۀ اِقرار وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24341, 'Luke 12:9', 'Luke', 12, 9, '&nbsp;خو څوک چې د خلقو په وړاندې زما نه اِنکار کوى نو د خُدائ پاک د فرښتو په وړاندې به د هغۀ نه اِنکار وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24342, 'Luke 12:10', 'Luke', 12, 10, '&nbsp;هر هغه څوک چې د اِبن آدم په خلاف څۀ خبره وکړى نو هغه به وبخښلے شى، خو څوک چې د روحُ القُدس په خلاف کُفر ووائى نو هغه به معاف نۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24343, 'Luke 12:11', 'Luke', 12, 11, '&nbsp;کله چې تاسو د عبادتخانو او د حاکمانو او د اختيار د خاوندانو په وړاندې د عدالت دپاره ودرولے شئ نو په دې وخت کښې اندېښنه مۀ کوئ چې تاسو به د دوئ په وړاندې په خپله صفائى کښې څۀ وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24344, 'Luke 12:12', 'Luke', 12, 12, '&nbsp;ځکه چې روحُ القُدس به هغه ساعت تاسو ته وښائى چې څۀ وئيل په کار دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24345, 'Luke 12:13', 'Luke', 12, 13, '&nbsp;په ګڼه کښې يو سړى عيسىٰ ته ووئيل، ”اُستاذه، زما ورور ته ووايه چې زما سره د ميراث تقسيم وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24346, 'Luke 12:14', 'Luke', 12, 14, '&nbsp;هغۀ جواب ورکړو چې، ”وروره، زۀ چا ستاسو منصف او ثالث مقرر کړے يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24347, 'Luke 12:15', 'Luke', 12, 15, '&nbsp;بيا هغۀ خلقو ته وفرمائيل، ”خبردار شئ. د هر قِسم حرص نه ځان ساتئ ځکه چې د بنى آدم ژوند په ډېر مال دولت پورې تړلے نۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24348, 'Luke 12:16', 'Luke', 12, 16, '&nbsp;او بيا ورته عيسىٰ دا مِثال پېش کړو چې، ”يو مالداره سړے وو چې په زمکه کښې يې ښۀ فصل وشو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24349, 'Luke 12:17', 'Luke', 12, 17, '&nbsp;هغۀ د ځان سره ووئيل، ما ته څۀ کول پکار دى؟ ما سره خو دومره ځائ هم نشته چې دا غله په کښې انبار کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24350, 'Luke 12:18', 'Luke', 12, 18, '&nbsp;بيا هغۀ ووئيل چې زۀ به داسې وکړم چې خپلې خمبې به ونړوم او لوئې به يې جوړې کړم او په هغې کښې به خپله ټوله غله او نور مال دولت سمبال کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24351, 'Luke 12:19', 'Luke', 12, 19, '&nbsp;او بيا به خپل ځان ته ووايم، سړيه، ډېر څيزونه دې جمع کړل چې د ډېرو کالونو پورې ستا دپاره کافى دى، اوس په آرام ژوند کوه، خوره څښه او خوشحاله ګرځه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24352, 'Luke 12:20', 'Luke', 12, 20, '&nbsp;خو خُدائ پاک هغۀ ته وفرمائيل، اے کم عقله. هم په دې شپه به دې ساه وخېژى. او تا چې کوم مال دولت راجمع کړو، دا به اوس د چا شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24353, 'Luke 12:21', 'Luke', 12, 21, '&nbsp;دا د هغه چا مِثال دے چا چې د خپل ځان دپاره مال دولت راجمع کړو، خو دے د خُدائ پاک په نزد مالداره نۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24354, 'Luke 12:22', 'Luke', 12, 22, '&nbsp;بيا هغۀ خپلو مريدانو ته وفرمائيل، ”ځکه زۀ تاسو ته دا وايم چې د خپل ژوندون دپاره دا اندېښنې مۀ کوئ چې، څۀ به خورو يا څۀ به اغوندو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24355, 'Luke 12:23', 'Luke', 12, 23, '&nbsp;ځکه چې ژوندون د روټۍ او بدن د جامو نه بهتر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24356, 'Luke 12:24', 'Luke', 12, 24, '&nbsp;کارغانو ته وګورئ، دوئ نۀ خو کَرى او نۀ رېبى، نۀ خو د دوئ ذخيرې شته، نۀ خمبې، خو بيا هم خُدائ پاک هغوئ له رزق ورکوى. نو بيا تاسو هغۀ ته د مارغانو په نسبت ډېر اهم يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24357, 'Luke 12:25', 'Luke', 12, 25, '&nbsp;په تاسو کښې داسې څوک شته چې هغه په اندېښنو خپل ژوند يو ساعت قدرې زيات کړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24358, 'Luke 12:26', 'Luke', 12, 26, '&nbsp;کۀ چرې تاسو دا معمولى کار قدرې هم نۀ شئ کولے نو بيا نورو اندېښنو ولې اخستى يئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24359, 'Luke 12:27', 'Luke', 12, 27, '&nbsp;ځنګلى ګلونو ته خو لږ خيال وکړئ، نۀ خو هغوئ خوارى کوى او نۀ ځان دپاره جامې جوړوى خو زۀ تاسو ته دا وايم چې سليمان چرې هم سره د خپل ټول شان او شوکت د دې ګلونو په شان ښائسته جامې اچولې نۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24360, 'Luke 12:28', 'Luke', 12, 28, '&nbsp;خو کۀ چرې خُدائ پاک د پټو واښو ته داسې جامې ورکوى، کوم چې نن شته او سبا په تنور کښې غورزولے شى، نو ولې هغه به بيا تاسو له ښکلې جامې درنۀ کړى څۀ؟ اے د کم ايمان خاوندانو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24361, 'Luke 12:29', 'Luke', 12, 29, '&nbsp;نو ځکه تاسو د خوراک څښاک پسې منډې مۀ وهئ، تاسو د دې څيزونو اندېښنه مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24362, 'Luke 12:30', 'Luke', 12, 30, '&nbsp;ځکه چې د دُنيا نور قومونه په دې څيزونو پسې په منډه دى خو ستاسو پلار د مخکښې نه ستاسو د حاجتونو نه ښۀ خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24363, 'Luke 12:31', 'Luke', 12, 31, '&nbsp;خو تاسو د هر څۀ نه اول د هغۀ د بادشاهۍ په لټون کښې شئ نو بيا به هغه ستاسو ټول حاجتونه پوره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24364, 'Luke 12:32', 'Luke', 12, 32, '&nbsp;اے وړې قبيلې. مۀ يرېږئ. ځکه چې ستاسو د پلار دا خوښه ده چې تاسو له بادشاهى درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24365, 'Luke 12:33', 'Luke', 12, 33, '&nbsp;خپل مال حال خرڅ کړئ او حاجتمندو ته يې ورکړئ او د ځان دپاره داسې بټوې تيارې کړئ چې هيڅکله نۀ زړيږى او خپل ځان له په آسمان کښې داسې خزانې جوړې کړئ چې هيڅکله نۀ ختميږى، چرته چې نۀ غل شته او نۀ وينۀ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24366, 'Luke 12:34', 'Luke', 12, 34, '&nbsp;ځکه چې چرته ستا خزانه وى هلته به ستا زړۀ هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24367, 'Luke 12:35', 'Luke', 12, 35, '&nbsp;د خِدمت دپاره تيار اوسئ او خپلې ډيوې بلې ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24368, 'Luke 12:36', 'Luke', 12, 36, '&nbsp;د هغو سړو په شان شئ څوک چې د خپل مالِک د وادۀ د روټۍ نه د واپس راتلو په اِنتظار وى نو چې هغه څۀ وخت راشى، او ور وټکوى نو چې سمدستى هغوئ ورته ور کولاو کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24369, 'Luke 12:37', 'Luke', 12, 37, '&nbsp;هغه خادِمان بختور دى چې مالِک يې د خپل راتلو په وخت بېدار ووينى. زۀ تاسو ته رښتيا وايم چې مالِک به په خپله د کار جامې واچوى او دوئ به خوراک ته کښېنوى او په خپله به د دوئ خِدمت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24370, 'Luke 12:38', 'Luke', 12, 38, '&nbsp;بختور دى هغه خادِمان کله چې د هغوئ مالِک په نيمه شپه او يا سحر سبا راشى او هغه دوئ بېدار ووينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24371, 'Luke 12:39', 'Luke', 12, 39, '&nbsp;خو ياد ساتئ، کۀ د کور مالِک خبر وے چې غل به د شپې په کوم وخت کښې راځى نو هغه به بېدار وے او خپل کور به يې کنډر کېدو ته پرېښے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24372, 'Luke 12:40', 'Luke', 12, 40, '&nbsp;نو بيا تاسو هم تيار اوسئ ځکه چې اِبن آدم به په داسې وخت کښې راځى چې ستاسو به په خيال خاطر کښې هم نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24373, 'Luke 12:41', 'Luke', 12, 41, '&nbsp;پطروس ووئيل چې، ”مالِکه، تۀ دا مِثال يواځې مونږ ته وائې او کۀ ټولو ته؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
