(24376, 'Luke 12:44', 'Luke', 12, 44, '&nbsp;زۀ تاسو ته رښتيا وايم چې مالِک به دۀ ته د خپل ټول مال واک اختيار ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24377, 'Luke 12:45', 'Luke', 12, 45, '&nbsp;خو کۀ هغه نوکر د خپل ځان سره داسې ووائى چې بويه چې زما مالِک راځى او بيا د نورو نوکرانو په وهلو لاس پورې کړى او په خوړلو او څښلو آخته وى او په نشه کښې وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24378, 'Luke 12:46', 'Luke', 12, 46, '&nbsp;نو مالِک به يې په داسې ورځ راشى چې د دۀ په خيال خاطر کښې به نۀ وى او په داسې وخت به راشى چې هغه به خبر هم نۀ وى، نو هغه به يې په وهلو تک شين کړى او په بې‌ايمانانو کښې به يې وشميرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24379, 'Luke 12:47', 'Luke', 12, 47, '&nbsp;خو هغه نوکر چې د خپل مالِک په طبيعت پوهيږى خو بيا هم د هغۀ په مرضۍ عمل ونۀ کړى، هغه به سخت وهل وخورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24380, 'Luke 12:48', 'Luke', 12, 48, '&nbsp;خو څوک چې د خپل مالِک په مرضۍ نۀ پوهيږى او غلط کارونه کوى نو د هغۀ سزا به لږه وى. کوم سړى ته چې زيات ورکړے شوے وى د هغۀ نه به زيات تپوس کولے شى او څومره زيات چې چا ته څۀ سپارلے شوى وى، هومره زيات به د هغۀ نه غوښتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24381, 'Luke 12:49', 'Luke', 12, 49, '&nbsp;زۀ دې له راغلے يم چې په زمکه اور پورې کړم او زما دا څومره خواهش وو چې دا د مخکښې نه بل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24382, 'Luke 12:50', 'Luke', 12, 50, '&nbsp;زۀ به د يوې سختې بپتسمې نه تېرېږم او د هغې د پوره کېدو پورې به په ما دروند بار وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24383, 'Luke 12:51', 'Luke', 12, 51, '&nbsp;ولې تاسو دا سوچ کوئ چې زۀ دُنيا ته د امن راوستو دپاره راغلے يم؟ خو زۀ د دې دپاره راغلے يم چې خلق په خپلو کښې جدا کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24384, 'Luke 12:52', 'Luke', 12, 52, '&nbsp;د دې نه پس به په يو کور کښې پينځۀ تنه خپلو کښې بې‌اتفاقه شى، درې به د دوو خلاف او دوه به د درېو خلاف شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24385, 'Luke 12:53', 'Luke', 12, 53, '&nbsp;دوئ به په خپلو کښې مخالفت شروع کړى، پلار به د زوئ او زوئ به د پلار خلاف، مور به د لور او لور به د مور خلاف، خواښې به د اِنږور او اِنږور به د خواښې خلاف شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24386, 'Luke 12:54', 'Luke', 12, 54, '&nbsp;عيسىٰ خلقو ته دا هم وفرمائيل، ”هر کله چې تاسو نمرپرېواتۀ طرف ته وريځې په راختو ووينئ نو تاسو بيا زر دا وايئ چې باران کېدونکے دے نو بيا هم داسې باران وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24387, 'Luke 12:55', 'Luke', 12, 55, '&nbsp;او هر کله چې باد د جنوب د طرفه وى نو تاسو وايئ چې د ګرمۍ چپه راتلونکى ده او هم داسې وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24388, 'Luke 12:56', 'Luke', 12, 56, '&nbsp;اے مُنافقانو. تاسو د زمکې او د آسمان حالت معلومولے شئ نو بيا تاسو څنګه د اوسنۍ زمانې په حالت نۀ پوهېږئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
