(24394, 'Luke 13:3', 'Luke', 13, 3, '&nbsp;بلکل نه، زۀ تاسو ته وايم چې، خو کۀ تاسو هم توبه ګار نۀ شئ نو ټول به هم هغه شان تباه شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24395, 'Luke 13:4', 'Luke', 13, 4, '&nbsp;يا هغه اتلس کسان چې په سيلوم کښې پرې برج راونړېدو او دوئ ترې لاندې مړۀ شول، ستاسو دا خيال دے چې هغوئ په يروشلم کښې د اوسېدونکو ټولو خلقو نه زيات ګناه ګار وُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24396, 'Luke 13:5', 'Luke', 13, 5, '&nbsp;بلکل نه، زۀ تاسو ته دا وايم چې کۀ تاسو توبه ګار نۀ شوئ نو ټول به هم هغه شان تباه شئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24397, 'Luke 13:6', 'Luke', 13, 6, '&nbsp;بيا عيسىٰ دا مِثال وفرمائيلو چې، ”د يو سړى په باغ کښې د اينځر ونه ولاړه وه. نو هغه مېوې لټولو له ورغلو خو هيڅ يې په کښې پېدا نۀ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24398, 'Luke 13:7', 'Luke', 13, 7, '&nbsp;نو هغۀ باغوان ته ووئيل، ګوره، د تېرو درېو کالو راسې زۀ په دې اينځر کښې د مېوې لټولو په طمع راځم خو هيڅ مېوه په کښې نۀ وى. نو بس دا د بېخه وباسه. دې هسې ځائ نيولے دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24399, 'Luke 13:8', 'Luke', 13, 8, '&nbsp;خو باغوان جواب ورکړو، صاحبه، سږ کال يې پرېږده، مۀ يې وباسه چې زۀ ورته ځائ جوړ کړم او سَره ورله ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24400, 'Luke 13:9', 'Luke', 13, 9, '&nbsp;کۀ په راتلونکى موسم کښې يې مېوه ونيوله نو ډېر ښۀ، ګنې بيا يې د بېخه وباسه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');